# Auswahl für den kompakten Abschnitt im Reiseversicherungs-Ratgeber
KOMPAKT=['tf-bank-mastercard-gold','advanzia-bank-free-mastercard-gold','n26-go','raiffeisen-platinum','erste-bank-und-sparkassen-premiumcard',
         'bank-austria-world','american-express-gold-card','american-express-platinum-card','diners-club-vintage','revolut-premium']

def _tbl(head,rows):
    h=''.join(f'<th>{c}</th>' for c in head)
    b=''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)
    return f'<div class="tbl wide"><table><thead><tr>{h}</tr></thead><tbody>{b}</tbody></table></div>'

def register(art,P,best,K,nprv,eur):
    T={c['slug']:c for c in K}
    for s,*_ in STORNO+DELAY:
        if s not in T: raise SystemExit(f'ratgeber_reise: unbekannte Karte {s}')
    def L(slug,label=None): return f'<a class="lnk" href="{P}at/kreditkarten/{slug}/">{E(label or T[slug]["titel"])}</a>'
    def fee(slug):
        c=T[slug]; f=c.get('fee')
        t='kostenlos' if f==0 else (f'{eur(f)} €' if f is not None else 'keine Angabe')
        return t+(' <small>(nur für bestimmte Gruppen)</small>' if c.get('nurfuer') else '')
    priv=[c for c in K if c['art']=='Privat']
    n_storno=len([c for c in priv if (c.get('tier') or 0)>=2]); n_basis=len([c for c in priv if c.get('tier')==1]); n_none=len([c for c in priv if c.get('tier')==0])
    D={s:r for s,*r in DELAY}
    reisen=f'{best}reisen/'
    storno=_tbl(['Karte','Jahresgebühr','Storno bis','Selbstbehalt Storno','Arztkosten bis','Max. Reisedauer','Was du tun musst'],
                [(L(s),fee(s),E(a),E(b),E(c),E(d),E(e)) for s,a,b,c,d,e in STORNO])
    delay=_tbl(['Karte','Gepäck verloren oder gestohlen bis','Koffer verspätet','Flug verspätet','Verpasster Flug, Abschleppen, Ski'],
               [(L(s),E(a),E(b),E(c),E(d)) for s,a,b,c,d in DELAY])
    kompakt=_tbl(['Karte','Jahresgebühr','Gepäck verloren bis','Koffer verspätet','Flug verspätet'],
                 [(L(s),fee(s),E(D[s][0]),E(D[s][1]),E(D[s][2])) for s in KOMPAKT])
    duel=_tbl(['',L('tf-bank-mastercard-gold'),L('advanzia-bank-free-mastercard-gold')],[
        ('<b>Selbstbehalt Storno</b>','100 € pro Person, fix','20 % des Schadens, mindestens 100 € pro Person'),
        ('<b>Bedingung</b>','50 % der Beförderungskosten (Flug, Bahn) mit der Karte; bei Autoreise 50 % der Unterkunft','50 % der Reisekosten; die Bedingungen widersprechen sich, ob Transport oder gesamte Reise gemeint ist'),
        ('<b>Altersgrenzen</b>','Rücktritt gilt nicht über 75; Kranken- und Rücktransport enden mit 75; Unfall zahlt ab 67 weniger (ab 68 höchstens 12.500 €)','Ab 70 nur 21 Tage pro Reise versichert; zur Grenze 75 widersprechen sich die Bedingungen'),
        ('<b>Mitversichert</b>','Familienangehörige, wenn sie mitreisen','Bis zu drei Mitreisende: Partner im selben Haushalt, Kinder unter 18, in Ausbildung bis 23'),
        ('<b>Gepäck und Verspätung</b>','Gepäck 2.500 € ohne Selbstbehalt; Koffer über 6 Stunden verspätet 150 €; Verpflegung 85 €; verpasste Abreise 300 €','Gepäck 2.500 € mit 100 € Selbstbehalt; Koffer oder Reise verspätet je 250 €'),
        ('<b>Einkaufsschutz</b>','nicht in den Reisebedingungen','Ja: 250 € pro Artikel, 500 € pro Fall, 1.500 € pro Jahr, plus Garantieverlängerung und Preisschutz'),
        ('<b>Unfall-Selbstbehalt</b>','keiner genannt','185 €')])
    eu=_tbl(['Flugdistanz','Betreuung (Verpflegung, Hotel) ab','Ausgleichszahlung ab 3 Stunden Verspätung am Ziel'],[
        ('bis 1.500 km','2 Stunden','250 € pro Person'),
        ('über 1.500 km innerhalb der EU sowie 1.500 bis 3.500 km','3 Stunden','400 € pro Person'),
        ('über 3.500 km','4 Stunden','600 € pro Person')])
    ext=lambda u,t: f'<a class="lnk" href="{u}" target="_blank" rel="noopener">{t}</a>'
    Q_EU=ext('https://www.verbraucherzentrale.de/wissen/reise-mobilitaet/unterwegs-sein/fluggastrechte-auf-einen-blick-wann-habe-ich-welchen-anspruch-10366','Verbraucherzentrale')
    Q_REF=ext('https://www.airliners.de/fluggastrechte-stunden-schwelle-bleibt/88381','airliners.de')
    Q_MC=ext('https://www.test.de/Verlorenes-Gepaeck-Aerger-am-Gepaeckband-1767091-1768178/','Stiftung Warentest')
    Q_APF=ext('https://www.oesterreich.gv.at/de/themen/reisen_und_freizeit/passagier_und_fahrgastrechte/Seite.3450010','oesterreich.gv.at')

    # ---------- 1. Reiseversicherung über die Kreditkarte ----------
    art('at','reiseversicherung',
      h1='Reiseversicherung über die Kreditkarte: Welche Karte dich in Österreich wirklich absichert',
      mt='Kreditkarte mit Reiseversicherung: Vergleich für Österreich 2026 | Finvallo',
      desc='Welche Kreditkarten in Österreich eine Reiseversicherung mit Storno enthalten: Stornosummen, Selbstbehalt, Arztkosten und Altersgrenzen im Vergleich.',
      lede=f'{n_storno} von {nprv} Privatkarten haben einen Reiserücktritt dabei. Ob er zahlt, entscheiden drei Bedingungen, die in keiner Werbung stehen.',
      kurz=(f'Von den {nprv} Privatkarten in unserem Vergleich enthalten {n_storno} eine Reiseversicherung mit Reiserücktritt, {n_basis} nur einen Basisschutz und {n_none} gar keine; beim Rest fehlen auswertbare Bedingungen. '
            'Fast alle zahlen den Storno nur, wenn du die Reise oder zumindest die Anzahlung mit der Karte bezahlt hast, und fast alle behalten 20 % Selbstbehalt ein. '
            f'Ohne Jahresgebühr und trotzdem mit Storno bis 3.000 €: {L("tf-bank-mastercard-gold")} und {L("advanzia-bank-free-mastercard-gold")}, dazu die {L("easybank-gold-student")} bis zum 27. Geburtstag. '
            f'Die höchsten Stornosummen haben {L("n26-go")} und {L("n26-metal")} mit 10.000 € und die {L("bank-austria-world-elite")} mit 10.000 € bei voller Kartenzahlung. '
            'Bei TF Bank endet der Rücktrittsschutz mit 75, Advanzia versichert ab 70 nur noch 21 Tage pro Reise, American Express gilt bis 80.'),
      secs=[
       ('Was „Reiseversicherung inklusive“ wirklich heißt',f'''<div class="prose"><p>Hinter dem Wort stecken bis zu vier getrennte Verträge, und keine Karte hat automatisch alle: Reiserücktritt und Reiseabbruch (Storno), Auslandsreise-Krankenversicherung mit Rücktransport, Gepäck- und Verspätungsschutz, und Unfall- oder Haftpflichtversicherung auf Reisen. Eine Mietwagen-Kasko hat in unserer Recherche die {L("american-express-platinum-card")} (75.000 €), {L("revolut-metal")} und {L("revolut-ultra")} erstatten die Selbstbeteiligung des Vermieters bis 2.000 €. Ein „umfassender Reiseschutz“ allein heißt nicht, dass der Mietwagen versichert ist.</p>
<p>Die {L("paylife-classic")} ist ein gutes Beispiel dafür, wie wenig „Reiseschutz“ bedeuten kann: Sie enthält nur eine Basis-Assistance, also Hilfe im Notfall, aber keine Krankenversicherung und keinen Storno. Die {L("oberbank-mastercard-klassik")} zahlt den Rücktransport nach Österreich, aber nicht die Behandlung davor. Die {L("american-express-card")} versichert Arztkosten bis 110.000 € und Gepäck bis 2.200 €, einen Reiserücktritt gibt es nicht.</p>
<p>Was eine Karte wirklich enthält, steht nur in den Versicherungsbedingungen. Wir haben sie für jede Karte gelesen; die Summen in diesem Artikel sind Höchstgrenzen aus diesen Dokumenten, keine fixen Auszahlungen.</p></div>'''),
       ('Die drei Bedingungen, an denen es im Schadenfall scheitert',f'''<div class="prose"><p><b>1. Die Reise muss mit der Karte bezahlt sein.</b> Das ist die häufigste Falle, und jede Bank legt die Schwelle anders fest. TF Bank verlangt, dass mindestens 50 % der Beförderungskosten über die Karte liefen, bei Anreise mit dem Auto 50 % der Unterkunft. Advanzia schreibt 50 % der Reisekosten, wobei Seite 3 der Bedingungen die Transportkosten meint und Seite 9 die gesamte Reise inklusive Unterkunft; diesen Widerspruch sollte man sich vor einer teuren Buchung schriftlich klären lassen. Diners Club will die Reise „überwiegend“ mit der Karte bezahlt und die Anzahlung vollständig. American Express verlangt für alles außer der Krankenversicherung die vollständige Zahlung mit der Karte oder mit Membership-Rewards-Punkten. PayLife setzt für die Unfallversicherung in Verkehrsmitteln 75 % Kartenzahlung voraus. Bei Revolut müssen Hauptverkehrsmittel und Unterkunft über das Revolut-Konto bezahlt sein, und der Tarif muss seit der Buchung durchgehend aktiv gewesen sein.</p>
<p>Viele Hausbank-Karten koppeln nicht den Schutz an die Zahlung, sondern die Höhe: {L("bank-austria-gold")} zahlt Storno bis 1.500 €, bei Kartenzahlung bis 3.000 €; {L("bawag-gold")} 1.500 € oder 3.000 € mit Anzahlung per Karte; {L("erste-bank-und-sparkassen-premiumcard")} 3.000 €, bei voller Kartenzahlung 5.000 € und dann mit 10 statt 20 % Selbstbehalt.</p>
<p><b>2. Die Karte muss vorher benutzt worden sein.</b> card complete, bank99, Diners Club, Raiffeisen, Bank Direkt und Bank Austria verlangen mindestens eine Kartennutzung in den zwei Monaten vor dem Schaden, BAWAG und Oberbank in den letzten drei Monaten. Wer die Karte nur für den Notfall im Safe liegen hat, ist mit diesen Karten nicht versichert. Die Erste Premiumcard ist die Ausnahme: Dort gilt der Schutz durch den Besitz der Karte, auch ohne Zahlung.</p>
<p><b>3. Bestellfristen und Wartefristen.</b> card complete, bank99 und die Erste-Karten zahlen Storno nur, wenn die Karte mindestens 30 Tage vor der Abreise beziehungsweise vor dem Schadenfall aktiv war. BAWAG hat eine Wartefrist für Reisen, die vor dem Kartenantrag gebucht wurden. Wer die Karte zwei Wochen vor dem Urlaub bestellt, um ihn abzusichern, hat bei diesen Anbietern nichts davon.</p></div>'''),
       ('Alle Karten mit Reiserücktritt im Vergleich','<p class="note">Sortiert nach Anbieter. „Storno bis“ ist die Höchstsumme für den Reiserücktritt; wo zwei Summen stehen, gilt die höhere bei (Teil-)Zahlung mit der Karte. „Arztkosten“ ist die Auslandsreise-Krankenversicherung. Karten, die es nur für bestimmte Gruppen gibt (Studierende, GÖD-Mitglieder), sind gekennzeichnet.</p>'+storno+
        f'''<div class="prose"><p>Die {L("card-complete-classic-mit-versicherung")} führen wir in der Bewertung als Basisschutz, weil ihre Krankenversicherung nur die Erstversorgung deckt; ihre Bedingungen enthalten aber einen Reiserücktritt bis 2.500 €, deshalb steht sie in der Tabelle. Nicht in der Tabelle, weil die Bedingungen keinen Reiserücktritt enthalten oder wir sie noch nicht vollständig ausgewertet haben: {L("american-express-card")} (Arztkosten 110.000 €), {L("card-complete-student")} (Reiseschutz laut Anbieter), {L("paylife-classic")} (Basis-Assistance), {L("easybank-kreditkarte")} (Basis-Reisekrankenversicherung), {L("oberbank-mastercard-klassik")} (Rücktransport, aber keine Arztkosten). Gar keine Reiseversicherung haben card complete Classic ohne Versicherung, card complete Prepaid, Erste Smartcard, Raiffeisen Classic, Bank Austria Classic, BAWAG Weiß, bank99 Classic, Santander Card, Revolut Standard und Plus, N26 Standard und Smart, Trade Republic und Wise.</p>
<p class="note"><a class="lnk" href="{reisen}">Bestenliste für Reisen →</a></p></div>'''),
       ('Kostenlos und trotzdem versichert: TF Bank gegen Advanzia','<div class="prose"><p>Beide Gratiskarten versichern Storno bis 3.000 €, Arztkosten bis 1.000.000 €, Gepäck bis 2.500 € (3.000 € für die Gruppe), Unfall bis 40.000 € und Haftpflicht bis 350.000 €. Die Unterschiede liegen im Kleingedruckten, und sie sind größer, als die identischen Summen vermuten lassen.</p></div>'+duel+
        f'''<div class="prose"><p>Bei einer stornierten Pauschalreise für 2.000 € zahlt TF Bank 1.900 € (2.000 € minus 100 €), Advanzia 1.600 € (20 % Selbstbehalt sind 400 €). Bei 600 € Schaden zahlt TF Bank 500 €, Advanzia 480 € (20 % sind 120 €). Je teurer die Reise, desto deutlicher liegt TF Bank vorn. Advanzia punktet dafür bei Familien mit Kindern bis 23, bei Verspätungen und beim Einkaufsschutz. Beide Karten verzinsen Bargeld ab dem Behebungstag; wer das nicht will, findet in der <a class="lnk" href="{reisen}">Bestenliste für Reisen</a> die Alternativen mit Jahresgebühr.</p></div>'''),
       ('Flugverspätung, Koffer verspätet oder verloren: was die Karten zahlen',f'''<div class="prose"><p>Bei Verspätungen und Gepäck ist die Karte der zweite Topf. Zuerst haftet die Airline: nach der EU-Fluggastrechteverordnung mit 250 bis 600 € ab drei Stunden Verspätung am Ziel, nach dem Montrealer Übereinkommen für Gepäck bis 1.519 Sonderziehungsrechte, rund 1.900 €. Die Kartenversicherung ersetzt obendrauf belegte Ausgaben, etwa Ersatzkäufe, wenn der Koffer später kommt, und den Teil eines Kofferinhalts über der gesetzlichen Grenze. Drei Zahlen entscheiden: ab wie vielen Stunden sie zahlt, wie viel, und wie hoch die Grenze für Wertsachen ist.</p></div>'''+kompakt+
        f'''<div class="prose"><p class="note">Zehn Karten als Querschnitt. Die Schwellen reichen von zwei Stunden ({L("n26-go")}) bis zwölf Stunden ({L("bank-austria-world-elite")} beim Gepäck), die Summen für verlorenes Gepäck von 1.000 € (Revolut) bis 5.000 € (card complete Platinum, bank99 Platinum, Raiffeisen Platinum, Bank Direkt Platinum, Bank Austria World Elite). Alle Karten, der Rechtsrahmen, Rechenbeispiele und die Schritte im Schadenfall stehen im eigenen Ratgeber: <a class="lnk" href="../flugverspaetung-gepaeck/">Flugverspätung, Koffer verspätet oder verloren: Was deine Kreditkarte zahlt →</a></p></div>'''),
       ('Altersgrenzen: ab wann der Schutz endet','''<div class="prose"><p>Hier unterscheiden sich die Karten am stärksten, und hier steht es am seltensten im Prospekt. Die Grenzen aus den Bedingungen:</p><ul>
<li><b>67 Jahre:</b> TF Bank zahlt bei Unfällen ab 67 weniger, ab 68 höchstens 12.500 € statt 40.000 €.</li>
<li><b>70 Jahre:</b> Advanzia versichert ab 70 nur noch 21 Tage pro Reise statt 90, ohne gebuchte Rückreise 35 Tage.</li>
<li><b>75 Jahre:</b> Bei TF Bank gilt der Reiserücktritt nicht mehr, die Kranken- und Rücktransportversicherung endet. Bei Advanzia widersprechen sich die Dokumente zur Grenze 75.</li>
<li><b>80 Jahre:</b> American Express Gold, Platinum und BMW Card: Krankenversicherung bis 80.</li>
<li><b>Keine Grenze genannt:</b> Bei card complete, bank99, Diners Club, PayLife, Erste, Raiffeisen, Bank Austria, BAWAG, Oberbank, Revolut und N26 haben wir in den ausgewerteten Bedingungen keine Altersgrenze gefunden. Das heißt nicht, dass es keine gibt; Revolut schließt zum Beispiel Vorerkrankungen der letzten zwölf Monate aus, was ältere Reisende häufiger trifft. Vor einer Reise ab 70 lohnt sich eine schriftliche Anfrage beim Anbieter.</li></ul>
<p>Für Pensionistinnen und Pensionisten heißt das: Die beiden Gratiskarten sind ab 75 beim Storno wertlos. Die Erste Premiumcard (Schutz durch Besitz, 180 Tage, Arztkosten ohne Limit) oder die Raiffeisen Gold sind dann die naheliegenden Alternativen, sofern die jeweilige Bank keine eigene Grenze nennt.</p></div>'''),
       ('Wer ist mitversichert?','''<div class="prose"><p>Die Regeln reichen von „nur du“ bis „deine Kinder auch allein“:</p><ul>
<li><b>Nur der Karteninhaber</b> bei der Krankenversicherung: PayLife GoldPlus, PayLife Black, PayLife Platinum, BAWAG Gold, easybank Gold, Oberbank Gold, Raiffeisen Gold. Partner und Kinder brauchen dort eine eigene Absicherung für Arztkosten.</li>
<li><b>Familie auf gemeinsamen Reisen:</b> TF Bank (Familienangehörige), card complete und bank99 (Partner mit mindestens drei Monaten gleicher Meldeadresse, minderjährige Kinder), Diners Club (Partner und Kinder), Raiffeisen Platinum (Familie laut Bedingungen), Revolut Metal und Ultra (Partner und Kinder bis 17), Revolut Premium (nur Kinder bis 17), N26 Go und Metal (Partner und Kinder bis 25 in Ausbildung).</li>
<li><b>Begrenzte Gruppe:</b> Advanzia versichert dich plus bis zu drei Mitreisende, für Kinder gilt eine Ausnahme von der Höchstzahl.</li>
<li><b>Kinder auch allein:</b> Die Erste Premiumcard versichert Kinder im Haushalt bis 27 auch auf eigenen Reisen, allerdings nicht beim Reiserücktritt.</li>
<li><b>Amex:</b> Kinder bis unter 23 (Gold Card) beziehungsweise unter 25 (Platinum Card), wenn sie laut Bedingungen zur Familie zählen.</li></ul>
<p>Bei PayLife Black und Platinum sowie Bank Austria World Elite gelten die Stornosummen pro Jahr für alle Versicherten zusammen. Eine Familie, die zweimal im Jahr storniert, erreicht die Grenze schneller als die Zahl auf dem Papier vermuten lässt.</p></div>'''),
       ('Wie lange darf eine Reise dauern?','''<div class="prose"><p>Der Standard sind 90 Tage pro Reise. Nach oben weichen die Erste-Karten mit 180 Tagen und die Amex Platinum mit 120 Tagen (höchstens 240 pro Jahr) ab, nach unten Revolut Premium und Metal mit 30 Tagen; Revolut Ultra kommt auf 90. Für ein Auslandssemester oder eine längere Südostasien-Reise fallen die Revolut-Tarife damit aus; die Amex Platinum hat dafür einen eigenen Schutz bis 365 Tage für ein Ausbildungs- oder Lückenjahr.</p>
<p>Wichtig bei Advanzia und Raiffeisen: Dauert eine Reise länger als erlaubt, ist laut Bedingungen nicht nur die Zeit danach unversichert, sondern die ganze Reise kann ohne Schutz sein. Wer 95 Tage unterwegs ist, hat dann ab Tag eins nichts.</p></div>'''),
       ('Selbstbehalt: von 0 € bis 20 % plus Mindestbetrag','''<div class="prose"><ul>
<li><b>Kein Selbstbehalt:</b> PayLife Black beim Reiserücktritt; GÖD Premiumcard bei voller Kartenzahlung; N26 beim Reiseabbruch.</li>
<li><b>Fixbetrag:</b> N26 20 € pro Person beim Rücktritt; TF Bank 100 € pro Person.</li>
<li><b>Prozent mit Deckel:</b> Revolut 10 %, höchstens 50 €.</li>
<li><b>Prozent mit Mindestbetrag:</b> Advanzia 20 %, mindestens 100 € pro Person.</li>
<li><b>20 % ohne Deckel:</b> card complete, bank99, Diners Club, PayLife GoldPlus, Bank Austria, BAWAG (10 % mit Anzahlung per Karte), easybank, Oberbank, Erste (10 % bei voller Kartenzahlung).</li>
<li><b>Nicht genannt:</b> American Express, Raiffeisen, Bank Direkt, PayLife Platinum. Dort steht in den Dokumenten, die wir ausgewertet haben, kein Selbstbehalt; wir würden vor einer Buchung trotzdem nachfragen.</li></ul>
<p>Bei einer 4.000-Euro-Reise sind 20 % immerhin 800 €. Die Karten mit Fixbetrag oder Deckel (TF Bank, N26, Revolut) sind bei teuren Reisen deshalb spürbar besser als ihre Stornosumme allein zeigt.</p></div>'''),
       ('Reicht die Kreditkarte, oder brauchst du eine eigene Polizze?','''<div class="prose"><p>Die Kreditkarten-Versicherung reicht in der Regel, wenn alle fünf Punkte zutreffen: Die Reise kostet weniger als die Stornosumme deiner Karte, sie dauert kürzer als die erlaubte Höchstdauer, du bist unter der Altersgrenze, du hast die Reise mit der Karte bezahlt beziehungsweise die Karte zuletzt benutzt, und es reisen nur Personen mit, die laut Bedingungen mitversichert sind.</p>
<p>Eine eigene Reiseversicherung brauchst du dagegen, wenn die Pauschalreise für die Familie 6.000 € kostet und deine Karte 3.000 € mit 20 % Selbstbehalt versichert; wenn jemand über 75 mitreist; wenn eine Vorerkrankung besteht, denn die ist bei fast allen Karten ausgeschlossen; wenn du länger als 90 Tage unterwegs bist; oder wenn du einen Mietwagen nimmst und nicht die Amex Platinum oder Revolut Ultra hast. Auch Kreuzfahrten, Sportreisen und Länder mit Reisewarnung sind häufig ausgeschlossen; die genauen Listen stehen in den Bedingungen jeder Karte.</p>
<p>Ein Mittelweg, den viele nicht kennen: Die Krankenversicherung über die Karte nutzen, die bei den meisten Karten großzügig ist (TF Bank, Advanzia und PayLife Black je 1.000.000 €, Revolut 10.000.000 €, Diners Club und Erste ohne Limit), und nur den Storno für die eine teure Reise separat versichern.</p></div>'''),
       ('Was im Schadenfall zu tun ist','''<div class="prose"><p>Vor jeder Behandlung im Ausland die Notfallnummer der Versicherung anrufen, nicht die der Bank. Advanzia rät in den Bedingungen ausdrücklich dazu, und bei Diners Club entfällt der 10-Prozent-Selbstbehalt nur, wenn deine gesetzliche Krankenversicherung zuerst zahlt. Belege aufheben: Buchungsbestätigung, Kartenabrechnung mit der Reisezahlung, ärztliches Attest beim Storno, Polizeiprotokoll bei Diebstahl. Fristen stehen in den Bedingungen; bei den meisten Versicherern musst du die Reise sofort absagen, sobald der Grund eintritt, sonst zahlen sie nur die Stornokosten, die zu diesem Zeitpunkt angefallen wären. Was bei Flugverspätung und Gepäck zu tun ist, steht Schritt für Schritt im <a href="../flugverspaetung-gepaeck/">Ratgeber zu Flugverspätung und Gepäck</a>.</p></div>'''),
      ],
      faq=[
       ('Gilt die Reiseversicherung der Kreditkarte automatisch?','Selten. Bei der Erste Premiumcard und der Oberbank Klassik reicht der Besitz. Die meisten anderen Karten verlangen, dass du die Karte in den letzten zwei bis drei Monaten benutzt hast, und für den Reiserücktritt zusätzlich, dass du die Reise oder die Anzahlung mit der Karte bezahlt hast.'),
       ('Welche kostenlose Kreditkarte hat eine Reiseversicherung mit Storno?','In Österreich zwei: TF Bank Mastercard Gold und Advanzia free Mastercard Gold, beide mit Reiserücktritt bis 3.000 € und Arztkosten bis 1.000.000 €. Die easybank Gold Student ist bis zum 27. Geburtstag gratis und versichert Storno bis 1.500 €, mit Anzahlung per Karte bis 2.500 €.'),
       ('Wie hoch ist der Selbstbehalt beim Reiserücktritt über die Kreditkarte?','Meist 20 % des Schadens. TF Bank zieht fix 100 € pro Person ab, Revolut 10 % bis höchstens 50 €, N26 20 € pro Person. PayLife Black und die GÖD Premiumcard bei voller Kartenzahlung haben keinen Selbstbehalt.'),
       ('Zahlt die Kreditkarte bei Flugverspätung zusätzlich zur Airline?','Ja, die Ansprüche sind getrennt. Die Airline schuldet die Ausgleichszahlung nach EU-Recht, die Kartenversicherung ersetzt belegte Ausgaben ab ihrer eigenen Schwelle, bei N26 ab zwei Stunden, bei den meisten Karten ab vier bis sechs Stunden. Details stehen im Ratgeber <a href="../flugverspaetung-gepaeck/">Flugverspätung und Gepäck</a>.'),
       ('Bis zu welchem Alter gilt die Reiseversicherung der Kreditkarte?','Bei TF Bank endet der Reiserücktritt mit 75, bei Advanzia schrumpft die versicherte Reisedauer ab 70 auf 21 Tage, bei American Express gilt die Krankenversicherung bis 80. Viele Hausbanken nennen in ihren Bedingungen keine Grenze; nachfragen lohnt sich trotzdem.'),
       ('Sind Partner und Kinder mitversichert?','Kommt auf die Leistung an. Bei PayLife, BAWAG, easybank, Oberbank und Raiffeisen Gold ist bei der Krankenversicherung nur der Karteninhaber versichert. TF Bank, Advanzia, card complete, Diners Club, N26 und Revolut Metal versichern Partner und Kinder auf gemeinsamen Reisen, mit unterschiedlichen Altersgrenzen für Kinder (17 bis 25 Jahre).'),
       ('Was ist der Unterschied zwischen Reiserücktritt und Reiseabbruch?','Reiserücktritt zahlt die Stornokosten, wenn du vor der Abreise absagen musst. Reiseabbruch zahlt die nicht genutzten Reiseleistungen und die Rückreise, wenn du unterwegs abbrechen musst. Viele Karten versichern beides mit derselben Summe (TF Bank, Advanzia, N26), andere den Abbruch niedriger (Diners Club 1.500 € statt 2.000 €, Raiffeisen Platinum 1.500 € statt 5.000 €).'),
       ('Zahlt die Kreditkarten-Versicherung auch beim Mietwagen?','Eine Mietwagen-Kasko hat in unserer Recherche die American Express Platinum Card (bis 75.000 €). Revolut Metal und Revolut Ultra erstatten die Selbstbeteiligung des Vermieters bis 2.000 €. Ein „umfassender Reiseschutz“ allein heißt nicht, dass der Mietwagen versichert ist. Was beim Mietwagen sonst zu beachten ist, steht im Ratgeber <a href="../mietwagen-kaution/">Mietwagen und Kaution</a>.'),
      ],
      related=['flugverspaetung-gepaeck','mietwagen-kaution','kostenlose-kreditkarte'])

    # ---------- 2. Flugverspätung, Koffer verspätet oder verloren ----------
    art('at','flugverspaetung-gepaeck',
      h1='Flugverspätung, Koffer verspätet oder verloren: Was deine Kreditkarte zahlt',
      mt='Flugverspätung und Gepäck: Was die Kreditkarte zahlt (Österreich) | Finvallo',
      desc='Was Kreditkarten in Österreich bei Flugverspätung und verspätetem oder verlorenem Gepäck zahlen: Schwellen in Stunden, Höchstsummen, Wertsachen-Grenzen.',
      lede='Die Airline haftet zuerst, die Karte legt nach. Wie viel, entscheiden drei Zahlen aus den Bedingungen: die Schwelle in Stunden, die Summe und die Grenze für Wertsachen.',
      kurz=(f'Von den {nprv} Privatkarten in unserem Vergleich nennen {len(DELAY)} konkrete Summen für verlorenes oder verspätetes Gepäck und für Flugverspätungen. '
            f'Die Schwellen reichen von zwei Stunden ({L("n26-go")}) bis zwölf Stunden ({L("bank-austria-world-elite")} beim Gepäck), die Summen für verlorenes Gepäck von 1.000 € (Revolut) bis 5.000 € (card complete Platinum, bank99 Platinum, Raiffeisen Platinum, Bank Direkt Platinum, Bank Austria World Elite). '
            'Unabhängig davon schuldet dir die Airline nach EU-Recht ab drei Stunden Verspätung 250 bis 600 € und haftet für Gepäck bis 1.519 Sonderziehungsrechte, rund 1.900 €. '
            'Die Karte ersetzt, was darüber hinausgeht oder was die Airline nicht zahlt, aber nur gegen Belege.'),
      secs=[
       ('Zwei Töpfe: die Airline zahlt zuerst, die Karte legt nach','''<div class="prose"><p>Bei Verspätung und Gepäck gibt es zwei Zahler, und sie funktionieren verschieden. Die Airline haftet aus dem Gesetz: Die EU-Fluggastrechteverordnung legt Pauschalen für Verspätungen fest, das Montrealer Übereinkommen regelt die Haftung für Gepäck. Diese Ansprüche hast du mit jeder Karte und auch ohne Karte. Die Versicherung deiner Kreditkarte ist ein Vertrag mit einem Versicherer, der obendrauf zahlt: Ersatzkäufe, wenn der Koffer nachkommt, Verpflegung und Hotel, wenn die Airline sie nicht stellt, und den Teil eines Kofferinhalts, der über die gesetzliche Grenze hinausgeht.</p>
<p>Zwei Dinge gelten bei fast allen Karten: Die Versicherung ersetzt nachgewiesene Ausgaben, keine Pauschalen, und sie zahlt nicht noch einmal, was die Airline schon ersetzt hat. Die Summen in diesem Artikel sind Höchstgrenzen aus den Bedingungen, die wir für jede Karte gelesen haben. Ob und wie viel du bekommst, hängt an drei Zahlen: ab wie vielen Stunden die Karte zahlt, bis zu welcher Summe, und wie hoch die Grenze für Wertsachen wie Kamera, Laptop oder Schmuck ist.</p></div>'''),
       ('Was die Airline zahlen muss: EU-Fluggastrechte und Montrealer Übereinkommen','''<div class="prose"><p>Kommst du mit mindestens drei Stunden Verspätung am Ziel an, steht dir nach der Verordnung (EG) 261/2004 eine Ausgleichszahlung zu, gestaffelt nach Flugdistanz. Die Airline kommt nur heraus, wenn sie außergewöhnliche und unvermeidbare Umstände nachweist, etwa Unwetter oder eine Sperre des Luftraums. Schon vorher muss sie dich betreuen: Verpflegung und zwei Telefonate oder E-Mails, bei einer Übernachtung das Hotel samt Transfer.</p></div>'''+eu+
        '''<div class="prose"><p class="note">Beträge pro Person. Eine 2026 ausgehandelte Reform der Verordnung lässt die Drei-Stunden-Schwelle und die Beträge unverändert; Airlines sollen Fluggäste künftig aktiver über ihre Ansprüche informieren.</p>
<p>Für Gepäck gilt das Montrealer Übereinkommen: Die Airline haftet für verlorenes, beschädigtes oder verspätetes Gepäck bis 1.519 Sonderziehungsrechte pro Passagier, umgerechnet rund 1.900 €. Das ist eine Obergrenze für den nachgewiesenen Schaden, keine Pauschale. Beschädigungen musst du binnen sieben Tagen schriftlich reklamieren, verspätetes Gepäck binnen 21 Tagen, nachdem du es zurückbekommen hast. Ist der Koffer nach 21 Tagen noch nicht da, gilt er als verloren. Ersatzkäufe bei Verspätung muss die Airline ersetzen, aber nur, was du wirklich brauchst; einen Teil kann sie abziehen, weil du die Kleidung behältst. Ansprüche aus dem Übereinkommen verjähren nach zwei Jahren.</p>
<p>Zahlt die Airline nicht oder meldet sie sich gar nicht, ist in Österreich die Agentur für Passagier- und Fahrgastrechte (apf) die Schlichtungsstelle für Fluggastbeschwerden.</p></div>'''),
       ('Alle Karten mit Gepäck- und Verspätungsschutz im Vergleich','<p class="note">Sortiert nach Anbieter. Alle Beträge sind Höchstsummen aus den Versicherungsbedingungen. „Koffer verspätet“ ist die Summe für Ersatzkäufe, „Flug verspätet“ die Summe für Verpflegung, Hotel und ähnliche Ausgaben. Steht keine Stundenzahl dabei, nennt die Bedingung keine Schwelle; „keine Angabe“ heißt, dass wir in den Bedingungen keinen Wert gefunden haben.</p>'+delay+
        f'''<div class="prose"><p>Nicht in der Tabelle: {L("easybank-kreditkarte-gold")} und {L("easybank-gold-student")} versichern laut Anbieter Gepäck, die Teilgrenzen haben wir noch nicht ausgewertet. Für {L("bawag-gold")} und {L("bawag-gold-student")} liegen uns zu Gepäck und Verspätung keine Angaben vor. Gar keinen Gepäck- oder Verspätungsschutz haben die Karten ohne Reiseversicherung: card complete Classic ohne Versicherung, card complete Prepaid, Erste Smartcard, Raiffeisen Classic, Bank Austria Classic, BAWAG Weiß, bank99 Classic, Santander Card, Revolut Standard und Plus, N26 Standard und Smart, Trade Republic und Wise.</p>
<p class="note"><a class="lnk" href="{reisen}">Bestenliste für Reisen →</a></p></div>'''),
       ('Flugverspätung: ab wann die Karte zahlt und wie viel',f'''<div class="prose"><p>Die Schwellen liegen zwischen zwei und acht Stunden. {L("n26-go")} und {L("n26-metal")} zahlen ab zwei Stunden 100 € für jede weitere Stunde, höchstens 500 €, und sind damit die einzigen Karten, die schon unterhalb der EU-Schwelle von drei Stunden etwas leisten. Bei vier Stunden beginnen American Express Gold und Platinum, Diners Club, Raiffeisen, Bank Direkt, Bank Austria World und World Elite sowie Revolut Ultra. TF Bank nennt für Flugverspätungen keine Schwelle, sondern bis 85 € für Verpflegung; die BMW Cards zahlen bis 200 € pro Person, aber nur, wenn das Ticket mit der Karte bezahlt wurde, dafür auch bei Annullierung. Revolut Premium zahlt erst ab acht Stunden. card complete, bank99, PayLife, Erste und Bank Austria Platinum nennen Summen ohne Stundenschwelle; dort entscheidet der Einzelfall nach den Bedingungen.</p>
<p>Ein Beispiel: Dein Flug von Wien nach Lissabon (rund 2.300 km) kommt vier Stunden zu spät an. Die Airline schuldet dir 400 € Ausgleichszahlung, außer sie weist außergewöhnliche Umstände nach, und ab drei Stunden Wartezeit Verpflegung. Die Karte zahlt zusätzlich für belegte Ausgaben: bis 250 € mit Raiffeisen Gold, bis 200 € mit N26 oder Amex Gold, bis 150 € mit Diners Club Classic, bis 85 € Verpflegung mit TF Bank; mit Revolut Premium nichts, weil die acht Stunden nicht erreicht sind. Die Kartenversicherung knüpft an die Dauer der Verspätung an; welche Ursachen ausgeschlossen sind, etwa angekündigte Streiks, steht in den Bedingungen jeder Karte.</p>
<p>Wichtig für den Antrag: Die Versicherung will eine Bestätigung der Airline über Dauer und Grund der Verspätung, dazu die Bordkarte und die Belege für Verpflegung oder Hotel. Ohne Bestätigung zahlt weder die Airline noch die Karte.</p></div>'''),
       ('Koffer verspätet: Ersatzkäufe und die 48-Stunden-Regel',f'''<div class="prose"><p>Kommt der Koffer nicht mit, zahlt die Karte Ersatzkäufe: Zahnbürste, Unterwäsche, ein Satz Kleidung, bei einer Skireise die Ausrüstung. Die Summen reichen von 150 € bei TF Bank und der American Express Card bis 600 € bei {L("diners-club-vintage")}; N26, Raiffeisen Platinum, Bank Direkt Platinum, Bank Austria World und World Elite zahlen bis 500 €, die Erste-Karten bis 450 €, PayLife Black und Platinum sowie Amex Platinum bis 400 €. American Express hat eine Besonderheit: Bei der Gold Card gibt es bis 300 € und nach 48 Stunden weitere 300 €, bei der Platinum Card 400 € plus 400 €, bei der Card und den BMW Cards 150 € plus 300 €. Wer zwei Tage ohne Koffer ist, bekommt dort also deutlich mehr als die erste Zahl.</p>
<p>Die Schwellen unterscheiden sich stärker als die Summen: Raiffeisen, Bank Direkt, N26, Amex Platinum, Bank Austria World und Revolut Ultra zahlen ab vier Stunden, TF Bank, die Amex Card und die BMW Cards ab sechs, Revolut Premium ab acht. {L("bank-austria-world-elite")} verlangt zwölf Stunden, die längste Wartezeit im Vergleich und bei 440 € Jahresgebühr die strengste Regel unter den Premiumkarten. Bank Austria Gold und Gold Student versichern verspätetes Gepäck gar nicht. Bei card complete, bank99 und Oberbank haben wir in den Bedingungen keinen Wert für verspätetes Gepäck gefunden.</p>
<p>Beispiel: Du landest abends in Palma, der Koffer kommt zwei Tage später. Du kaufst für 280 € Kleidung und Hygieneartikel, mit Belegen. Nach dem Montrealer Übereinkommen muss die Airline notwendige Ersatzkäufe ersetzen, kann aber einen Teil abziehen, weil du die Sachen behältst. Was offen bleibt, reichst du bei der Kartenversicherung ein: Mit Amex Gold wären bis 600 € gedeckt (300 € plus 300 € nach 48 Stunden), mit N26 oder Raiffeisen Platinum bis 500 €, mit Advanzia bis 250 €, mit TF Bank bis 150 €. Zweimal kassieren geht nicht: Was die Airline ersetzt hat, zieht die Versicherung ab.</p></div>'''),
       ('Koffer verloren oder gestohlen: Höchstsummen und Wertsachengrenzen',f'''<div class="prose"><p>Für den verlorenen oder gestohlenen Koffer gelten die höchsten Summen, aber auch die meisten Grenzen. Vorne liegen {L("card-complete-platinum")}, {L("bank99-platinum")}, {L("raiffeisen-platinum")}, {L("bank-direkt-platinum")} und {L("bank-austria-world-elite")} mit 5.000 €, dahinter die Erste-Karten und PayLife Platinum mit 4.500 €, die BMW Cards mit 4.400 €, Diners Club Vintage und PayLife Black mit 4.000 €. Die Gratiskarten TF Bank und Advanzia versichern 2.500 € pro Person (3.000 € für die Gruppe), Advanzia mit 100 € Selbstbehalt. Am unteren Ende stehen Revolut mit 1.000 € und Bank Austria Gold mit 1.500 €.</p>
<p>Entscheidend ist das Kleingedruckte zu Wertsachen: Amex Gold begrenzt einzelne Gegenstände auf 750 €, N26 Wertsachen auf 750 € und Dokumente auf 500 €, Amex Platinum Bargeld und Dokumente auf 1.500 €, die BMW Cards Wertsachen auf 1.500 € pro Stück. Eine Kamera um 2.400 € ist über diese Karten also höchstens zur Hälfte abgesichert. Bei den anderen Karten haben wir in den ausgewerteten Bedingungen keine Wertsachengrenze gefunden; das heißt nicht, dass es keine gibt. Wer teure Ausrüstung mitnimmt, ist mit einer eigenen Gepäck- oder Geräteversicherung besser dran; auch manche Haushaltsversicherungen decken Gepäck außer Haus mit, was in der Polizze steht.</p>
<p>So greifen die Töpfe ineinander: Geht ein Koffer mit 3.000 € Inhalt verloren, haftet die Airline bis rund 1.900 € für den nachgewiesenen Wert. Die Kartenversicherung ersetzt den Rest bis zu ihrer Höchstsumme, in der Regel zum Zeitwert und nicht zum Neupreis; bei Revolut ist bei 1.000 € insgesamt Schluss. Nachweisen musst du den Wert in beiden Fällen, am besten mit Kaufbelegen oder Fotos. Bei Diebstahl verlangen die Versicherer zusätzlich die Anzeige bei der Polizei vor Ort.</p></div>'''),
       ('Verpasster Anschluss, verpasste Abreise, Auto liegen geblieben',f'''<div class="prose"><p>Den versäumten Flug versichern nur wenige: {L("diners-club-vintage")} zahlt bis 3.000 €, Diners Club Classic, Gold, Golf und Student bis 1.500 €, jeweils wenn die Reise überwiegend mit der Karte bezahlt wurde. {L("tf-bank-mastercard-gold")} zahlt bis 300 €, wenn du die Abreise verpasst. Alle anderen Karten in unserem Vergleich nennen dafür keine Summe. Wer einen Anschlussflug auf einem getrennten Ticket bucht, trägt das Risiko also fast immer selbst; bei einem durchgehenden Ticket muss die Airline dich umbuchen.</p>
<p>Für die Anreise mit dem Auto gibt es bei einigen Karten Abschleppkosten: die Erste-Karten bis 450 €, {L("paylife-platinum")} bis 400 €. PayLife GoldPlus, Black, Platinum und die Erste-Karten zahlen außerdem bei Skibruch (220 €, 400 € beziehungsweise 450 €), {L("revolut-metal")} versichert Wintersportausrüstung bis 1.500 €.</p></div>'''),
       ('Schritt für Schritt: so kommst du an das Geld','''<div class="prose"><ol>
<li><b>Am Flughafen melden.</b> Fehlt der Koffer oder ist er beschädigt, gehst du vor dem Verlassen der Gepäckhalle zum Schalter der Airline oder zu Lost &amp; Found und lässt einen Property Irregularity Report (PIR) ausstellen. Er belegt, dass du rechtzeitig gemeldet hast, und enthält die Referenznummer für die Suche.</li>
<li><b>Bestätigung der Airline holen.</b> Bei Verspätung oder Annullierung brauchst du eine schriftliche Bestätigung über Dauer und Grund, am Schalter oder per E-Mail. Bordkarte und Buchung aufheben.</li>
<li><b>Belege sammeln.</b> Jede Ausgabe für Verpflegung, Hotel, Transfer oder Ersatzkäufe mit Rechnung. Nur Notwendiges kaufen; Pauschalen ohne Beleg zahlt keine Karte.</li>
<li><b>Fristen einhalten.</b> Beschädigtes Gepäck binnen sieben Tagen, verspätetes Gepäck binnen 21 Tagen nach der Rückgabe schriftlich bei der Airline reklamieren. Die Kartenversicherung hat eigene Meldefristen, die in den Bedingungen stehen; melde den Schaden so bald wie möglich.</li>
<li><b>Zuerst die Airline.</b> Ausgleichszahlung nach EU-Recht und Gepäckschaden nach dem Montrealer Übereinkommen bei der Airline beantragen. Die Kartenversicherung fragt nach dem Ergebnis, bevor sie zahlt.</li>
<li><b>Dann die Versicherung.</b> Den Schaden beim Versicherer melden, nicht bei der Bank: Die Nummer steht in den Versicherungsbedingungen deiner Karte. Mitschicken: PIR oder Airline-Bestätigung, Belege, Kartenabrechnung mit der Ticketzahlung, bei Diebstahl die Polizeianzeige.</li>
<li><b>Bei Ablehnung.</b> Reagiert die Airline nicht oder lehnt sie ab, kannst du dich in Österreich an die Agentur für Passagier- und Fahrgastrechte wenden. Bei Streit mit dem Versicherer helfen Verein für Konsumenteninformation und Arbeiterkammer weiter.</li></ol></div>'''),
       ('Welche Karte passt zu welchem Reisetyp',f'''<div class="prose"><ul>
<li><b>Viele Kurzstreckenflüge:</b> {L("n26-go")} oder {L("n26-metal")}: Flugverspätung ab zwei Stunden, 100 € pro Stunde bis 500 €, Gepäck ab vier Stunden bis 500 €. Keine andere Karte zahlt so früh.</li>
<li><b>Familie, Fernreise, Auto zum Flughafen:</b> {L("erste-bank-und-sparkassen-premiumcard")} (Gepäck 4.500 €, je 450 € für verspätetes Gepäck, Flugverspätung und Abschleppen, Schutz durch Kartenbesitz) oder {L("raiffeisen-platinum")} und {L("bank-direkt-platinum")} (Gepäck 5.000 €, je 500 € ab vier Stunden).</li>
<li><b>Ohne Jahresgebühr:</b> {L("tf-bank-mastercard-gold")} (Gepäck 2.500 €, 150 € ab sechs Stunden, 85 € Verpflegung, 300 € bei verpasster Abreise) oder {L("advanzia-bank-free-mastercard-gold")} (Gepäck 2.500 € mit 100 € Selbstbehalt, je 250 € bei Verspätung). Advanzia zahlt mehr bei Verspätung, TF Bank hat keinen Selbstbehalt beim Gepäck.</li>
<li><b>Premium:</b> {L("american-express-platinum-card")} (400 € plus 400 € nach 48 Stunden für den Koffer, 200 € pro Person beim Flug, Gepäck 3.000 €, nur nachgewiesene Ausgaben) oder {L("diners-club-vintage")} (Gepäck 4.000 €, 600 € Ersatzkäufe, 3.000 € bei versäumtem Flug).</li>
<li><b>Nicht darauf verlassen:</b> {L("revolut-premium")} und {L("revolut-metal")} (Gepäck nur 1.000 €, Premium erst ab acht Stunden), {L("bank-austria-gold")} (keine Verspätungsversicherung), {L("card-complete-classic-mit-versicherung")} (Gepäck 1.820 €, Flug 110 €).</li></ul></div>'''),
       ('Quellen und Rechtsgrundlagen',f'''<div class="prose"><ul>
<li>Verordnung (EG) Nr. 261/2004 über Fluggastrechte: Beträge und Betreuungsleistungen nach der Übersicht der {Q_EU}; zur 2026 ausgehandelten Reform {Q_REF}.</li>
<li>Montrealer Übereinkommen: Haftungsgrenze von 1.519 Sonderziehungsrechten, Fristen und Property Irregularity Report nach {Q_MC}.</li>
<li>Agentur für Passagier- und Fahrgastrechte als Schlichtungsstelle: {Q_APF}.</li>
<li>Versicherungssummen und Schwellen: Versicherungsbedingungen der Anbieter, verlinkt auf jeder Kartenseite.</li></ul></div>'''),
      ],
      faq=[
       ('Zahlt die Kreditkarte bei Flugverspätung, auch wenn die Airline schon 400 € gezahlt hat?','Ja. Die Ausgleichszahlung der Airline ist eine gesetzliche Pauschale, die Kartenversicherung ersetzt belegte Ausgaben wie Verpflegung oder Hotel ab ihrer eigenen Stundenschwelle. Nur Kosten, die die Airline bereits ersetzt hat, zieht die Versicherung ab.'),
       ('Ab wie vielen Stunden Verspätung zahlt die Kreditkarte?','N26 ab zwei Stunden; American Express Gold und Platinum, Diners Club, Raiffeisen, Bank Direkt, Bank Austria World und Revolut Ultra ab vier; TF Bank, Amex Card und BMW Cards beim Gepäck ab sechs; Revolut Premium ab acht; Bank Austria World Elite beim Gepäck ab zwölf. card complete, PayLife und Erste nennen Summen ohne Schwelle.'),
       ('Wie viel bekomme ich, wenn der Koffer zwei Tage zu spät kommt?','Die Karte ersetzt belegte Ersatzkäufe bis zu ihrer Summe: 600 € bei Diners Club Vintage, 500 € bei N26, Raiffeisen Platinum und Bank Austria World, 450 € bei den Erste-Karten, 150 € bei TF Bank. American Express zahlt nach 48 Stunden eine zweite Tranche, bei der Gold Card 300 € plus 300 €.'),
       ('Was gilt, wenn der Koffer ganz verloren ist?','Nach 21 Tagen gilt der Koffer als verloren. Die Airline haftet bis 1.519 Sonderziehungsrechte, rund 1.900 €. Darüber hinaus zahlt die Kartenversicherung bis zu ihrer Höchstsumme, zwischen 1.000 € bei Revolut und 5.000 € bei card complete Platinum, bank99 Platinum, Raiffeisen Platinum oder Bank Austria World Elite, gegen Nachweis des Werts.'),
       ('Muss ich verspätetes Gepäck noch am Flughafen melden?','Ja. Lass dir am Schalter der Airline oder bei Lost &amp; Found einen Property Irregularity Report (PIR) ausstellen, bevor du die Gepäckhalle verlässt. Airline und Kartenversicherung verlangen ihn als Nachweis; beschädigtes Gepäck musst du zusätzlich binnen sieben Tagen schriftlich reklamieren.'),
       ('Welche Kreditkarte zahlt bei Flugverspätung am meisten?','Bei langen Verspätungen Raiffeisen Platinum, Bank Direkt Platinum, Bank Austria World und World Elite, card complete Platinum und bank99 Platinum mit bis zu 500 €; N26 ebenfalls bis 500 € und schon ab zwei Stunden. Die Erste Premiumcard zahlt bis 450 € ohne Stundenschwelle in den Bedingungen.'),
       ('Zahlt die Kreditkarte, wenn ich den Anschlussflug verpasse?','Nur bei Diners Club (bis 1.500 €, Vintage bis 3.000 €, wenn die Reise überwiegend mit der Karte bezahlt wurde) und bei TF Bank (bis 300 € bei verpasster Abreise). Alle anderen Karten in unserem Vergleich nennen dafür keine Summe.'),
       ('Brauche ich trotz Kreditkarte eine Reisegepäckversicherung?','Wenn du mit Kamera, Laptop oder Sportausrüstung über 750 € reist, ja: Amex Gold und N26 begrenzen Einzelstücke auf 750 €, die BMW Cards auf 1.500 €, und die Airline haftet höchstens mit rund 1.900 € insgesamt. Für den normalen Urlaubskoffer reichen die meisten Karten mit 2.000 € oder mehr.'),
      ],
      related=['reiseversicherung','mietwagen-kaution','fremdwaehrung'])
